 uint8_t primary;for(unsigned command:{0u,1u,2u,0x101u}){check(scene.requestVisualCommand(uint16_t(command),error),"source secondary argument and low-byte semantics");check(scene.visualCommand(primary)&&primary==15&&!scene.visualBusy(),"secondary cannot replace primary caption owner");check(scene.render(kSceneReferenceRGB565,after,error)&&after.indexed==before.indexed&&after.rgb==before.rgb,"zero differing full canonical pixels on secondary admission");check(scene.scroll().nextMode==(uint8_t(command)==1?kScrollAbsolute:kScrollRelative),"absolute versus relative semantic marker");}
 check(scene.queueScrollPosition(0,kScrollX,5,error)&&scene.requestVisualCommand(1,error)&&scene.updateObjects(false,error)&&scene.scroll().positions[0].x16==5*65536,"absolute source request consumed by actual worker");check(scene.queueScrollPosition(0,kScrollX,3,error)&&scene.requestVisualCommand(2,error)&&scene.updateObjects(false,error)&&scene.scroll().positions[0].x16==8*65536,"relative source request adds rather than replaces");check(scene.requestVisualCommand(0,error)&&scene.queueScrollPosition(0,kScrollX,9,error)&&scene.updateObjects(false,error)&&scene.scroll().positions[0].x16==8*65536,"zero stops producer without erasing displayed position");check(scene.requestVisualCommand(2,error)&&scene.updateObjects(false,error)&&scene.scroll().positions[0].x16==17*65536,"restart consumes retained pending displacement");
 check(scene.requestVisualCommand(13,error)&&scene.visualBusy(),"primary animated menu owner");const auto threshold=scene.presentationLayout().viewBands;check(scene.requestVisualCommand(1,error)&&scene.visualBusy()&&scene.visualCommand(primary)&&primary==13&&scene.presentationLayout().viewBands.size()==threshold.size(),"secondary does not complete a primary transition");check(scene.beginFrame(true,error)&&scene.visualBusy(),"pause retains actual primary transition");
